/**
 * ExistingUserAddedBanner icon migration — asserts the Check icon uses
 * Lucide's Check component from @omnicore-platform/ui/icons.
 */

import { describe, expect, it, vi } from "vitest";
import { render } from "@testing-library/react";
import { ExistingUserAddedBanner } from "../../src/invite/ExistingUserAddedBanner";

describe("ExistingUserAddedBanner — Lucide icons", () => {
  it("renders the success Check icon via Lucide (lucide-check class)", () => {
    const { container } = render(
      <ExistingUserAddedBanner userID="uid-1" onDismiss={vi.fn()} />,
    );
    expect(container.querySelector(".lucide-check")).toBeInTheDocument();
  });

  it("Check icon is aria-hidden (decorative; heading text carries the status message)", () => {
    const { container } = render(
      <ExistingUserAddedBanner userID="uid-1" onDismiss={vi.fn()} />,
    );
    const icon = container.querySelector(".lucide-check");
    expect(icon).toHaveAttribute("aria-hidden", "true");
  });
});


