/**
 * InviteForm icon migration — asserts the AlertCircle (error alert) and
 * Loader2 (spinner) icons use Lucide components from @omnicore-platform/ui/icons.
 *
 * This test covers the invite/** 85% coverage gate so invite thresholds hold.
 */

import { describe, expect, it, vi, beforeEach } from "vitest";
import { render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { InviteForm } from "../../src/invite/InviteForm";
import * as api from "../../src/invite/api";
import * as tenantsApi from "../../src/api/tenants";
import { useSession, DEFAULT_CAPABILITIES } from "../../src/lib/useSession";

vi.mock("../../src/invite/api", () => ({
  inviteUser: vi.fn(),
}));

vi.mock("../../src/api/tenants", () => ({
  listTenants: vi.fn(),
}));

vi.mock("../../src/lib/useSession", async (importOriginal) => {
  const actual = await importOriginal<typeof import("../../src/lib/useSession")>();
  return {
    ...actual,
    useSession: vi.fn(),
  };
});

const DEFAULT_ORG_ID = "00000000-0000-0000-0000-000000000001";

const defaultOrg = {
  id: DEFAULT_ORG_ID,
  name: "Default Org",
  slug: "default-org",
  status: "active" as const,
  created_at: "2026-01-01T00:00:00Z",
  updated_at: "2026-01-01T00:00:00Z",
};

describe("InviteForm — Lucide icons", () => {
  const onSuccess = vi.fn();

  beforeEach(() => {
    vi.clearAllMocks();
    vi.mocked(useSession).mockReturnValue({
      state: "ready",
      session: {
        user_id: "u",
        org_id: DEFAULT_ORG_ID,
        roles: ["admin"],
        email: "a@b",
        tier: "platform",
        orgRole: "ADMIN",
        capabilities: { ...DEFAULT_CAPABILITIES, canInvite: true },
      },
    });
    vi.mocked(tenantsApi.listTenants).mockResolvedValue({
      tenants: [defaultOrg],
      next_page_token: "",
    });
  });

  it("renders the error alert icon via Lucide (lucide-alert-circle) when API fails", async () => {
    vi.mocked(api.inviteUser).mockRejectedValue(new Error("invite failed: 500"));
    const user = userEvent.setup();
    const { container } = render(<InviteForm onSuccess={onSuccess} />);

    // Fill all fields to get a valid form
    await user.type(screen.getByLabelText(/email/i), "alice@example.com");
    await user.type(screen.getByLabelText(/display name/i), "Alice");
    const orgSelect = await screen.findByRole("combobox", { name: /organization/i });
    await user.selectOptions(orgSelect, DEFAULT_ORG_ID);
    await user.click(screen.getByRole("button", { name: /send invite/i }));

    await screen.findByRole("alert");
    // AlertCircle is aliased to CircleAlert in lucide-react 1.x → class lucide-circle-alert
    expect(container.querySelector(".lucide-circle-alert")).toBeInTheDocument();
  });

  it("renders the spinner icon via Lucide (lucide-loader-2 or lucide-loader) while submitting", async () => {
    // Never resolve so the submitting state stays visible
    vi.mocked(api.inviteUser).mockImplementation(
      () => new Promise<{ user_id: string; temp_password: string }>(() => {}),
    );
    const user = userEvent.setup();
    const { container } = render(<InviteForm onSuccess={onSuccess} />);

    await user.type(screen.getByLabelText(/email/i), "alice@example.com");
    await user.type(screen.getByLabelText(/display name/i), "Alice");
    const orgSelect = await screen.findByRole("combobox", { name: /organization/i });
    await user.selectOptions(orgSelect, DEFAULT_ORG_ID);
    await user.click(screen.getByRole("button", { name: /send invite/i }));

    await waitFor(() =>
      expect(screen.getByRole("button", { name: /sending/i })).toBeInTheDocument(),
    );

    // Loader2 is aliased to LoaderCircle in lucide-react 1.x → class lucide-loader-circle
    const spinner =
      container.querySelector(".lucide-loader-circle") ??
      container.querySelector(".lucide-loader-2") ??
      container.querySelector(".lucide-loader");
    expect(spinner).toBeInTheDocument();
  });

  it("spinner icon is aria-hidden while submitting", async () => {
    vi.mocked(api.inviteUser).mockImplementation(
      () => new Promise<{ user_id: string; temp_password: string }>(() => {}),
    );
    const user = userEvent.setup();
    const { container } = render(<InviteForm onSuccess={onSuccess} />);

    await user.type(screen.getByLabelText(/email/i), "alice@example.com");
    await user.type(screen.getByLabelText(/display name/i), "Alice");
    const orgSelect = await screen.findByRole("combobox", { name: /organization/i });
    await user.selectOptions(orgSelect, DEFAULT_ORG_ID);
    await user.click(screen.getByRole("button", { name: /send invite/i }));

    await waitFor(() =>
      expect(screen.getByRole("button", { name: /sending/i })).toBeInTheDocument(),
    );

    const spinner =
      container.querySelector(".lucide-loader-circle") ??
      container.querySelector(".lucide-loader-2") ??
      container.querySelector(".lucide-loader");
    expect(spinner).toHaveAttribute("aria-hidden", "true");
  });
});


