import { describe, it, expect, vi, beforeEach } from "vitest";
import { render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { InviteForm } from "../../src/invite/InviteForm";
import * as api from "../../src/invite/api";
import * as tenantsApi from "../../src/api/tenants";
import type { AdminTenant, ListTenantsResult } from "../../src/api/tenants";
import { useSession, DEFAULT_CAPABILITIES } from "../../src/lib/useSession";

vi.mock("../../src/invite/api", () => ({
  inviteUser: vi.fn(),
}));

vi.mock("../../src/api/tenants", () => ({
  listTenants: vi.fn(),
}));

vi.mock("../../src/lib/useSession", async (importOriginal) => {
  const actual = await importOriginal<typeof import("../../src/lib/useSession")>();
  return {
    ...actual,
    useSession: vi.fn(),
  };
});

/** Minimal valid AdminTenant fixture — fills all required fields. */
function makeTenant(overrides: Partial<AdminTenant> & Pick<AdminTenant, "id" | "name">): AdminTenant {
  return {
    slug: overrides.name.toLowerCase().replace(/\s+/g, "-"),
    created_at: "2026-01-01T00:00:00Z",
    updated_at: "2026-01-01T00:00:00Z",
    status: "active",
    ...overrides,
  };
}

const mockResult = { user_id: "uid-1", temp_password: "tmp-pw" };

/** UUID-format org id used by default fixtures so uuidSchema validation passes. */
const DEFAULT_ORG_ID = "00000000-0000-0000-0000-000000000001";

const defaultOrg: AdminTenant = {
  id: DEFAULT_ORG_ID,
  name: "Default Org",
  slug: "default-org",
  status: "active",
  created_at: "2026-01-01T00:00:00Z",
  updated_at: "2026-01-01T00:00:00Z",
};

describe("InviteForm", () => {
  const onSuccess = vi.fn();

  beforeEach(() => {
    vi.clearAllMocks();
    // Default: platform tier — all existing tests keep their open-dropdown behaviour.
    vi.mocked(useSession).mockReturnValue({
      state: "ready",
      session: {
        user_id: "u",
        org_id: DEFAULT_ORG_ID,
        roles: ["admin"],
        email: "a@b",
        tier: "platform",
        orgRole: "ADMIN",
        capabilities: { ...DEFAULT_CAPABILITIES, canInvite: true },
      },
    });
    vi.mocked(tenantsApi.listTenants).mockResolvedValue({
      tenants: [defaultOrg],
      next_page_token: "",
    });
    // Default org_id used by fillAndSubmit must be a valid UUID.
    // The DEFAULT_ORG_ID constant above matches the defaultOrg fixture.
  });

  async function fillAndSubmit(
    user: ReturnType<typeof userEvent.setup>,
    overrides: Partial<{
      email: string;
      display_name: string;
      org_id: string;
    }> = {},
  ): Promise<void> {
    const email = overrides.email ?? "alice@example.com";
    const display_name = overrides.display_name ?? "Alice";
    const org_id = overrides.org_id ?? DEFAULT_ORG_ID;

    // userEvent v14 throws on user.type(el, "") — skip type when value is empty
    await user.clear(screen.getByLabelText(/email/i));
    if (email) await user.type(screen.getByLabelText(/email/i), email);
    await user.clear(screen.getByLabelText(/display name/i));
    if (display_name)
      await user.type(screen.getByLabelText(/display name/i), display_name);
    const orgSelect = await screen.findByRole("combobox", {
      name: /organization/i,
    });
    if (org_id) await user.selectOptions(orgSelect, org_id);
    await user.click(screen.getByRole("button", { name: /send invite/i }));
  }

  it("renders all required fields", async () => {
    render(<InviteForm onSuccess={onSuccess} />);
    expect(screen.getByLabelText(/email/i)).toBeInTheDocument();
    expect(screen.getByLabelText(/display name/i)).toBeInTheDocument();
    expect(
      await screen.findByRole("combobox", { name: /organization/i }),
    ).toBeInTheDocument();
    expect(
      screen.getByRole("button", { name: /send invite/i }),
    ).toBeInTheDocument();
  });

  it("calls onSuccess with result on happy path", async () => {
    vi.mocked(api.inviteUser).mockResolvedValue(mockResult);
    const user = userEvent.setup();
    render(<InviteForm onSuccess={onSuccess} />);
    await fillAndSubmit(user);
    await waitFor(() => expect(onSuccess).toHaveBeenCalledWith(mockResult));
  });

  it("passes correct payload to inviteUser", async () => {
    vi.mocked(api.inviteUser).mockResolvedValue(mockResult);
    const user = userEvent.setup();
    render(<InviteForm onSuccess={onSuccess} />);
    await fillAndSubmit(user);
    await waitFor(() =>
      expect(api.inviteUser).toHaveBeenCalledWith(
        expect.objectContaining({
          email: "alice@example.com",
          display_name: "Alice",
          org_id: DEFAULT_ORG_ID,
        }),
      ),
    );
  });

  it("blocks submission when email is empty", async () => {
    const user = userEvent.setup();
    render(<InviteForm onSuccess={onSuccess} />);
    await fillAndSubmit(user, { email: "" });
    await waitFor(() => expect(api.inviteUser).not.toHaveBeenCalled());
  });

  it("blocks submission when display_name is empty", async () => {
    const user = userEvent.setup();
    render(<InviteForm onSuccess={onSuccess} />);
    await fillAndSubmit(user, { display_name: "" });
    await waitFor(() => expect(api.inviteUser).not.toHaveBeenCalled());
  });

  it("blocks submission when org_id is empty", async () => {
    const user = userEvent.setup();
    render(<InviteForm onSuccess={onSuccess} />);
    await fillAndSubmit(user, { org_id: "" });
    await waitFor(() => expect(api.inviteUser).not.toHaveBeenCalled());
  });

  it("displays an inline error when the API call fails", async () => {
    vi.mocked(api.inviteUser).mockRejectedValue(
      new Error("invite failed: 500"),
    );
    const user = userEvent.setup();
    render(<InviteForm onSuccess={onSuccess} />);
    await fillAndSubmit(user);
    await waitFor(() => expect(screen.getByRole("alert")).toBeInTheDocument());
    expect(onSuccess).not.toHaveBeenCalled();
  });

  it("renders an Organization dropdown populated from listTenants and submits org_id only", async () => {
    const ORG_A_ID = "aaaaaaaa-0000-0000-0000-000000000001";
    const ORG_B_ID = "bbbbbbbb-0000-0000-0000-000000000002";
    const acme: AdminTenant = makeTenant({ id: ORG_A_ID, name: "Acme Corp" });
    const globex: AdminTenant = makeTenant({ id: ORG_B_ID, name: "Globex Inc" });
    const listTenantsResult: ListTenantsResult = {
      tenants: [acme, globex],
      next_page_token: "",
    };
    vi.mocked(tenantsApi.listTenants).mockResolvedValue(listTenantsResult);
    vi.mocked(api.inviteUser).mockResolvedValue({
      user_id: "new-uid",
      temp_password: "tmp-pw",
    });

    const user = userEvent.setup();
    render(<InviteForm onSuccess={onSuccess} />);

    // listTenants must be called with parent_id: "" to fetch root tenants
    await waitFor(() =>
      expect(tenantsApi.listTenants).toHaveBeenCalledWith({ parent_id: "" }),
    );

    // The Organization select must appear and contain both tenant options
    const orgSelect = await screen.findByRole("combobox", {
      name: /organization/i,
    });
    expect(orgSelect).toBeInTheDocument();
    expect(screen.getByRole("option", { name: "Acme Corp" })).toBeInTheDocument();
    expect(screen.getByRole("option", { name: "Globex Inc" })).toBeInTheDocument();

    // Fill email and display name
    await user.type(screen.getByLabelText(/email/i), "a@b.test");
    await user.type(screen.getByLabelText(/display name/i), "Test User");

    // Choose Globex Inc from the dropdown
    await user.selectOptions(orgSelect, ORG_B_ID);

    // Submit
    await user.click(screen.getByRole("button", { name: /send invite/i }));

    // inviteUser must be called with exactly {email, display_name, org_id} —
    // no tenant_id, no role
    await waitFor(() =>
      expect(api.inviteUser).toHaveBeenCalledWith({
        email: "a@b.test",
        display_name: "Test User",
        org_id: ORG_B_ID,
      }),
    );
    expect(api.inviteUser).toHaveBeenCalledTimes(1);
  });

  it("pre-selects the option matching initialOrgId when provided", async () => {
    const listTenantsResult: ListTenantsResult = {
      tenants: [
        makeTenant({ id: "uuid-org-a", name: "Acme" }),
        makeTenant({ id: "uuid-org-b", name: "Globex" }),
      ],
      next_page_token: "",
    };
    vi.mocked(tenantsApi.listTenants).mockResolvedValueOnce(listTenantsResult);

    render(<InviteForm onSuccess={onSuccess} initialOrgId="uuid-org-b" />);

    const combo = await screen.findByRole("combobox", { name: /organization/i });
    await waitFor(() => expect(combo).toHaveValue("uuid-org-b"));
  });

  // ── Org-tier dropdown lock ───────────────────────────────────────────────

  it("disables the Organization dropdown for org tier and pre-selects the user's org", async () => {
    vi.mocked(useSession).mockReturnValue({
      state: "ready",
      session: {
        user_id: "u",
        org_id: "uuid-org-a",
        roles: ["org-admin"],
        email: "a@b",
        tier: "org",
        orgRole: "ADMIN",
        capabilities: { ...DEFAULT_CAPABILITIES, canInvite: true },
      },
    });
    vi.mocked(tenantsApi.listTenants).mockResolvedValue({
      tenants: [
        makeTenant({ id: "uuid-org-a", name: "Acme" }),
        makeTenant({ id: "uuid-org-b", name: "Globex" }),
      ],
      next_page_token: "",
    } as ListTenantsResult);

    render(<InviteForm onSuccess={vi.fn()} />);

    const combo = await screen.findByRole("combobox", { name: /organization/i });
    await waitFor(() => expect(combo).toHaveValue("uuid-org-a"));
    expect(combo).toBeDisabled();
  });

  it("keeps the Organization dropdown enabled for platform tier", async () => {
    vi.mocked(useSession).mockReturnValue({
      state: "ready",
      session: {
        user_id: "u",
        org_id: "uuid-org-a",
        roles: ["admin"],
        email: "a@b",
        tier: "platform",
        orgRole: "ADMIN",
        capabilities: { ...DEFAULT_CAPABILITIES, canInvite: true },
      },
    });
    vi.mocked(tenantsApi.listTenants).mockResolvedValue({
      tenants: [
        makeTenant({ id: "uuid-org-a", name: "Acme" }),
        makeTenant({ id: "uuid-org-b", name: "Globex" }),
      ],
      next_page_token: "",
    } as ListTenantsResult);

    render(<InviteForm onSuccess={vi.fn()} />);

    const combo = await screen.findByRole("combobox", { name: /organization/i });
    // wait for orgs to load so disabled=orgsLoading clears
    await waitFor(() => expect(combo).not.toBeDisabled());
  });

  // ── Zod validation (Stage 2) ─────────────────────────────────────────────

  it("keeps submit disabled when email is invalid (not an email format)", async () => {
    const user = userEvent.setup();
    render(<InviteForm onSuccess={onSuccess} />);

    // Org must be present; fill display_name and org so only email is invalid
    await user.type(screen.getByLabelText(/display name/i), "Alice");
    const orgSelect = await screen.findByRole("combobox", { name: /organization/i });
    await user.selectOptions(orgSelect, DEFAULT_ORG_ID);

    // Type a value that is not a valid email
    await user.type(screen.getByLabelText(/email/i), "notanemail");

    expect(screen.getByRole("button", { name: /send invite/i })).toBeDisabled();
  });

  it("shows inline email error on blur with invalid input", async () => {
    const user = userEvent.setup();
    render(<InviteForm onSuccess={onSuccess} />);

    const emailInput = screen.getByLabelText(/email/i);
    await user.type(emailInput, "bad");
    await user.tab(); // blur

    expect(await screen.findByRole("alert")).toBeInTheDocument();
  });

  it("clears the email error and enables submit when all fields become valid", async () => {
    const user = userEvent.setup();
    vi.mocked(api.inviteUser).mockResolvedValue(mockResult);
    render(<InviteForm onSuccess={onSuccess} />);

    const emailInput = screen.getByLabelText(/email/i);
    // First blur with invalid to show error
    await user.type(emailInput, "bad");
    await user.tab();
    expect(await screen.findByRole("alert")).toBeInTheDocument();

    // Fix the email
    await user.clear(emailInput);
    await user.type(emailInput, "alice@example.com");
    await user.type(screen.getByLabelText(/display name/i), "Alice");
    const orgSelect = await screen.findByRole("combobox", { name: /organization/i });
    await user.selectOptions(orgSelect, DEFAULT_ORG_ID);

    await waitFor(() =>
      expect(screen.getByRole("button", { name: /send invite/i })).not.toBeDisabled(),
    );
  });

  it("does not call inviteUser when form is invalid on submit attempt", async () => {
    const user = userEvent.setup();
    render(<InviteForm onSuccess={onSuccess} />);

    // Type invalid email only
    await user.type(screen.getByLabelText(/email/i), "notvalid");
    // Submit button is disabled so clicking it should not fire
    const submit = screen.getByRole("button", { name: /send invite/i });
    expect(submit).toBeDisabled();
    await user.click(submit);

    expect(api.inviteUser).not.toHaveBeenCalled();
  });

  // ── Workspace + role pickers (option A — invite + add-to-workspace in one trip) ──

  it("loads workspaces when an org is selected and renders the picker", async () => {
    // Two roots, plus two workspaces under ORG_A.
    const ORG_A_ID = "aaaaaaaa-0000-0000-0000-000000000001";
    const WORKSPACE_X_ID = "11111111-0000-0000-0000-000000000001";
    const WORKSPACE_Y_ID = "11111111-0000-0000-0000-000000000002";
    const orgA = makeTenant({ id: ORG_A_ID, name: "Acme Corp" });
    const wsX = makeTenant({ id: WORKSPACE_X_ID, name: "Workspace X" });
    const wsY = makeTenant({ id: WORKSPACE_Y_ID, name: "Workspace Y" });

    // First call (parent_id: "") returns roots; second call (parent_id: ORG_A_ID)
    // returns the workspaces under it.
    vi.mocked(tenantsApi.listTenants)
      .mockResolvedValueOnce({ tenants: [orgA], next_page_token: "" })
      .mockResolvedValueOnce({ tenants: [wsX, wsY], next_page_token: "" });

    const user = userEvent.setup();
    render(<InviteForm onSuccess={onSuccess} />);

    const orgSelect = await screen.findByRole("combobox", { name: /organization/i });
    await user.selectOptions(orgSelect, ORG_A_ID);

    // Workspaces fetched with parent_id = selected org.
    await waitFor(() =>
      expect(tenantsApi.listTenants).toHaveBeenCalledWith({ parent_id: ORG_A_ID }),
    );

    // The Workspace dropdown appears with the children.
    const wsSelect = await screen.findByRole("combobox", { name: /workspace/i });
    expect(wsSelect).toBeInTheDocument();
    expect(screen.getByRole("option", { name: "Workspace X" })).toBeInTheDocument();
    expect(screen.getByRole("option", { name: "Workspace Y" })).toBeInTheDocument();
  });

  it("omits tenant_id and role from the payload when no workspace is selected", async () => {
    vi.mocked(api.inviteUser).mockResolvedValue(mockResult);
    const user = userEvent.setup();
    render(<InviteForm onSuccess={onSuccess} />);
    await fillAndSubmit(user);

    await waitFor(() => expect(api.inviteUser).toHaveBeenCalled());
    const arg = vi.mocked(api.inviteUser).mock.calls[0][0];
    expect(arg).not.toHaveProperty("tenant_id");
    expect(arg).not.toHaveProperty("role");
  });

  it("sends tenant_id and role when a workspace is picked", async () => {
    const ORG_A_ID = "aaaaaaaa-0000-0000-0000-000000000001";
    const WORKSPACE_X_ID = "11111111-0000-0000-0000-000000000001";
    vi.mocked(tenantsApi.listTenants)
      .mockResolvedValueOnce({
        tenants: [makeTenant({ id: ORG_A_ID, name: "Acme Corp" })],
        next_page_token: "",
      })
      .mockResolvedValueOnce({
        tenants: [makeTenant({ id: WORKSPACE_X_ID, name: "Workspace X" })],
        next_page_token: "",
      });
    vi.mocked(api.inviteUser).mockResolvedValue(mockResult);

    const user = userEvent.setup();
    render(<InviteForm onSuccess={onSuccess} />);

    await user.type(screen.getByLabelText(/email/i), "alice@example.com");
    await user.type(screen.getByLabelText(/display name/i), "Alice");
    const orgSelect = await screen.findByRole("combobox", { name: /organization/i });
    await user.selectOptions(orgSelect, ORG_A_ID);

    const wsSelect = await screen.findByRole("combobox", { name: /workspace/i });
    await user.selectOptions(wsSelect, WORKSPACE_X_ID);

    const roleSelect = await screen.findByRole("combobox", { name: /role/i });
    await user.selectOptions(roleSelect, "ADMIN");

    await user.click(screen.getByRole("button", { name: /send invite/i }));

    await waitFor(() =>
      expect(api.inviteUser).toHaveBeenCalledWith({
        email: "alice@example.com",
        display_name: "Alice",
        org_id: ORG_A_ID,
        tenant_id: WORKSPACE_X_ID,
        role: "ADMIN",
      }),
    );
  });

  // ── Non-Error rejection ─────────────────────────────────────────────────────

  it("surfaces a generic error message when inviteUser rejects with a non-Error value", async () => {
    // Line 140: `err instanceof Error ? err.message : m.invite_error_generic()`
    // The non-Error branch uses the localized generic message.
    vi.mocked(api.inviteUser).mockRejectedValue("string error, not an Error object");
