  };
});

/** Minimal valid AdminTenant fixture — fills all required fields. */
function makeTenant(overrides: Partial<AdminTenant> & Pick<AdminTenant, "id" | "name">): AdminTenant {
  return {
    slug: overrides.name.toLowerCase().replace(/\s+/g, "-"),
    created_at: "2026-01-01T00:00:00Z",
    updated_at: "2026-01-01T00:00:00Z",
    status: "active",
    ...overrides,
  };
}

const mockResult = { user_id: "uid-1", temp_password: "tmp-pw" };

/** UUID-format org id used by default fixtures so uuidSchema validation passes. */
const DEFAULT_ORG_ID = "00000000-0000-0000-0000-000000000001";

const defaultOrg: AdminTenant = {
  id: DEFAULT_ORG_ID,
  name: "Default Org",
  slug: "default-org",
  status: "active",
  created_at: "2026-01-01T00:00:00Z",
  updated_at: "2026-01-01T00:00:00Z",
};

