        user_id: "u",
        org_id: DEFAULT_ORG_ID,
        roles: ["admin"],
        email: "a@b",
        tier: "platform",
        orgRole: "ADMIN",
        capabilities: { ...DEFAULT_CAPABILITIES, canInvite: true },
      },
    });
    vi.mocked(tenantsApi.listTenants).mockResolvedValue({
      tenants: [defaultOrg],
      next_page_token: "",
    });
    // Default org_id used by fillAndSubmit must be a valid UUID.
    // The DEFAULT_ORG_ID constant above matches the defaultOrg fixture.
  });

  async function fillAndSubmit(
    user: ReturnType<typeof userEvent.setup>,
    overrides: Partial<{
      email: string;
      display_name: string;
      org_id: string;
    }> = {},
  ): Promise<void> {
    const email = overrides.email ?? "alice@example.com";
    const display_name = overrides.display_name ?? "Alice";
    const org_id = overrides.org_id ?? DEFAULT_ORG_ID;

    // userEvent v14 throws on user.type(el, "") — skip type when value is empty
    await user.clear(screen.getByLabelText(/email/i));
    if (email) await user.type(screen.getByLabelText(/email/i), email);
    await user.clear(screen.getByLabelText(/display name/i));
    if (display_name)
      await user.type(screen.getByLabelText(/display name/i), display_name);
    const orgSelect = await screen.findByRole("combobox", {
      name: /organization/i,
