    expect(toast).toHaveAttribute("data-variant", "error");
    expect(toast).toHaveTextContent(/manually/i);
  });

  describe("with fake timers", () => {
    // Fake only setTimeout/clearTimeout. The default fake-timers config
    // also intercepts queueMicrotask, which prevents the promise chain
    // inside `copy()` (await navigator.clipboard.writeText) from
    // resolving — the toast never appears, the test never advances.
    beforeEach(() => {
      vi.useFakeTimers({ toFake: ["setTimeout", "clearTimeout"] });
    });

    afterEach(() => {
      vi.useRealTimers();
    });

    it("auto-dismisses the toast after ~3 seconds", async () => {
