        fireEvent.click(screen.getByRole("button", { name: /copy/i }));
      });

      expect(screen.getByTestId("copy-toast")).toBeInTheDocument();

      await act(async () => {
        vi.advanceTimersByTime(3000);
      });

      expect(screen.queryByTestId("copy-toast")).not.toBeInTheDocument();
    });
