import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { inviteUser } from "../../src/invite/api";
import type { InviteRequest } from "../../src/invite/api";

const VALID_UUID_RE =
  /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

const mockRequest: InviteRequest = {
  email: "alice@example.com",
  display_name: "Alice",
  org_id: "org-1",
};

describe("inviteUser", () => {
  beforeEach(() => {
    vi.stubGlobal(
      "fetch",
      vi.fn().mockResolvedValue({
        ok: true,
        json: async () => ({ user_id: "uid-1", temp_password: "tmp-pw" }),
      }),
    );
  });

  afterEach(() => {
    vi.unstubAllGlobals();
  });

  it("POSTs to the correct endpoint", async () => {
    await inviteUser(mockRequest);
    expect(vi.mocked(fetch)).toHaveBeenCalledWith(
      "/api/v1/admin/users/invite",
      expect.objectContaining({ method: "POST" }),
    );
  });

  it("sends credentials: include", async () => {
    await inviteUser(mockRequest);
    expect(vi.mocked(fetch)).toHaveBeenCalledWith(
      expect.any(String),
      expect.objectContaining({ credentials: "include" }),
    );
  });

  it("includes a valid UUID Idempotency-Key header", async () => {
    await inviteUser(mockRequest);
    const [, init] = vi.mocked(fetch).mock.calls[0] as [
      string,
      RequestInit & { headers: Record<string, string> },
    ];
    const key = (init.headers as Record<string, string>)["Idempotency-Key"];
    expect(key).toMatch(VALID_UUID_RE);
  });

  it("uses a fresh Idempotency-Key on each call", async () => {
    await inviteUser(mockRequest);
    await inviteUser(mockRequest);
    const keys = vi
      .mocked(fetch)
      .mock.calls.map(
        ([, init]) =>
          (
            (init as RequestInit & { headers: Record<string, string> })
              .headers as Record<string, string>
          )["Idempotency-Key"],
      );
    expect(keys[0]).not.toBe(keys[1]);
  });

  it("sends the correct POST body shape", async () => {
    await inviteUser(mockRequest);
    const [, init] = vi.mocked(fetch).mock.calls[0] as [string, RequestInit];
    expect(JSON.parse(init.body as string)).toEqual(mockRequest);
  });

  it("returns the result from response body", async () => {
    const result = await inviteUser(mockRequest);
    expect(result).toEqual({ user_id: "uid-1", temp_password: "tmp-pw" });
  });

  it("unwraps body.data envelope when present", async () => {
    vi.stubGlobal(
      "fetch",
      vi.fn().mockResolvedValue({
        ok: true,
        json: async () => ({
          data: { user_id: "uid-2", temp_password: "tmp-pw-2" },
        }),
      }),
    );
    const result = await inviteUser(mockRequest);
    expect(result).toEqual({ user_id: "uid-2", temp_password: "tmp-pw-2" });
  });

  it("throws when response is not ok", async () => {
    vi.stubGlobal(
      "fetch",
      vi.fn().mockResolvedValue({ ok: false, status: 403 }),
    );
    await expect(inviteUser(mockRequest)).rejects.toThrow("invite failed: 403");
  });
});



